const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const file=process.env.TARGET_FILE,sha=process.env.TARGET_SHA,blob=process.env.TARGET_BLOB,hash=process.env.TARGET_HASH,bytes=Number(process.env.TARGET_BYTES);const ok=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
ok(sh('git rev-parse HEAD')===sha,'wrong parent');ok(sh(`git hash-object ${file}`)===blob,'blob drift');const src=fs.readFileSync(file,'utf8'),had=src.endsWith('\n'),lines=src.replace(/\n$/,'').split('\n');const remove=[240,239,129,127,78,77,76,75];for(const n of remove){ok(lines[n-1]!==undefined,`missing line ${n}`);lines.splice(n-1,1);}fs.writeFileSync(file,lines.join('\n')+(had?'\n':''));const stat=sh(`git diff --numstat -- ${file}`).split(/\s+/);ok(stat[0]==='0'&&stat[1]==='8'&&stat[2]===file,'diff drift');const buf=fs.readFileSync(file),actual=crypto.createHash('sha256').update(buf).digest('hex');ok(actual===hash,`hash drift ${actual}`);ok(buf.length===bytes,`bytes drift ${buf.length}`);cp.execSync('git diff --check');console.log(`PROMOTION BUILD PASS|hash=${actual}|bytes=${buf.length}|files=1|additions=0|deletions=8`);
